    (function(){
      const q=new URLSearchParams(location.search);
      try{
        if(q.get('utilityra_owner')==='exclude')localStorage.setItem('ur-owner-exclude','1');
        if(q.get('utilityra_owner')==='include')localStorage.removeItem('ur-owner-exclude');
      }catch(e){}
      if(q.has('utilityra_owner')){q.delete('utilityra_owner');const clean=location.pathname+(q.toString()?'?'+q.toString():'')+location.hash;history.replaceState(null,'',clean);}
    })();




:root{color-scheme:dark;--bg:#08090f;--surface:#11131d;--surface2:#171a27;--ink:#f7f8ff;--muted:#a7adbf;--line:rgba(255,255,255,.11);--violet:#805bff;--violet2:#5b3acb;--teal:#8df0df;--shadow:0 28px 80px rgba(0,0,0,.32);--radius:24px;--font:'Inter',system-ui,-apple-system,'Segoe UI',sans-serif;--display:'DM Sans','Inter',system-ui,sans-serif}
*{box-sizing:border-box}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%;scroll-padding-top:90px}
body{margin:0;background:var(--bg);color:var(--ink);font:400 15px/1.65 var(--font);overflow-x:hidden}
a{color:inherit;text-decoration:none}
button,input,textarea,select{font:inherit}
button{cursor:pointer}
button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:2px solid var(--teal);outline-offset:4px}
.to-wrap{width:min(1240px,calc(100% - 48px));margin-inline:auto}
.to-topline{border-bottom:1px solid rgba(255,255,255,.06);background:#08090f;color:#a6adbf;font-size:11px;letter-spacing:.025em}
.to-topline .to-wrap{display:flex;justify-content:space-between;gap:18px;align-items:center;min-height:31px}
.to-topline strong{color:#f8f8ff;font-weight:800;letter-spacing:.14em}
.to-header{position:sticky;top:0;z-index:50;border-bottom:1px solid rgba(255,255,255,.075);background:rgba(8,9,15,.78);backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px)}
.to-nav{min-height:76px;display:flex;align-items:center;gap:28px}
.to-logo{display:inline-flex;align-items:center;gap:11px;white-space:nowrap;font:700 23px/1 var(--display);letter-spacing:-.07em}
.to-mark{width:37px;height:37px;display:grid;place-items:center;position:relative;overflow:hidden;border:1px solid rgba(255,255,255,.18);border-radius:12px;background:linear-gradient(140deg,#926bff,#4e37b8 62%,#20a99f);box-shadow:0 8px 30px rgba(117,78,255,.28);font-size:18px;color:white}
.to-mark:after{content:"";position:absolute;inset:1px;border-radius:10px;border:1px solid rgba(255,255,255,.2);pointer-events:none}
.to-logo .to-word{color:#f7f7ff}.to-logo .to-word em{font-style:normal;color:var(--teal)}
.to-links{display:flex;align-items:center;gap:clamp(13px,2vw,27px);margin-inline:auto}
.to-links a{color:#c4c6d2;font-size:12px;font-weight:550;white-space:nowrap;transition:color .2s}
.to-links a:hover{color:#fff}
.to-actions{display:flex;align-items:center;gap:9px}
.to-btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;min-height:42px;padding:0 17px;border:1px solid transparent;border-radius:999px;white-space:nowrap;font-size:12px;font-weight:750;transition:transform .22s,background .22s,border-color .22s,color .22s}
.to-btn:hover{transform:translateY(-2px)}
.to-btn-primary{color:#fff;background:linear-gradient(115deg,#6b46de,#8b65ff);box-shadow:0 10px 32px rgba(111,76,227,.25)}
.to-btn-primary:hover{background:linear-gradient(115deg,#7956eb,#9a7bff)}
.to-btn-quiet{background:rgba(255,255,255,.045);border-color:rgba(255,255,255,.12);color:#e7e8f2}
.to-btn-quiet:hover{background:rgba(255,255,255,.09);border-color:rgba(255,255,255,.2)}
.to-arrow{font-size:16px;line-height:1}
.to-toolswitch{display:flex;align-items:center;gap:6px}.to-switch{width:36px;height:36px;border:1px solid rgba(255,255,255,.12);border-radius:50%;background:rgba(255,255,255,.04);color:#dfe1ef;font-size:11px;font-weight:800}.to-switch:hover{background:rgba(255,255,255,.1)}
.to-burger{display:none;width:43px;height:43px;border:1px solid var(--line);border-radius:50%;background:#171924;color:#fff;font-size:19px}
.to-mobile-menu{display:none;position:absolute;top:calc(100% + 8px);inset-inline:16px;padding:10px;border:1px solid rgba(255,255,255,.12);border-radius:19px;background:rgba(15,16,25,.96);backdrop-filter:blur(22px);box-shadow:0 24px 70px #0009;z-index:70}
.to-mobile-menu.open{display:grid;animation:toMenuIn .22s cubic-bezier(.16,1,.3,1) both}
.to-mobile-menu a{padding:13px 14px;border-radius:12px;color:#e3e4ee;font-size:14px}
.to-mobile-menu a:hover{background:rgba(255,255,255,.07)}
@keyframes toMenuIn{from{opacity:0;transform:translateY(-7px) scale(.985)}to{opacity:1;transform:none}}
.to-hero{position:relative;isolation:isolate;overflow:hidden;min-height:min(780px,calc(100svh - 108px));display:flex;align-items:center;padding:76px 0 80px;border-bottom:1px solid rgba(255,255,255,.06);background:radial-gradient(ellipse at 77% 43%,rgba(100,63,220,.14),transparent 43%),#090a11}
.to-hero:before{content:"";position:absolute;inset:0;z-index:-1;opacity:.16;background-image:linear-gradient(rgba(255,255,255,.065) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.065) 1px,transparent 1px);background-size:44px 44px;mask-image:linear-gradient(to right,transparent 0%,black 42%,black 100%);pointer-events:none}
.to-hero:after{content:"";position:absolute;width:640px;height:640px;right:-200px;top:-300px;border-radius:50%;background:radial-gradient(circle,rgba(123,83,255,.17),transparent 68%);z-index:-1;pointer-events:none}
.to-hero-grid{display:grid;grid-template-columns:minmax(0,1.03fr) minmax(400px,.97fr);align-items:center;gap:clamp(30px,5vw,76px);position:relative}
.to-hero-copy{position:relative;z-index:3;max-width:650px}
.to-eyebrow{display:inline-flex;align-items:center;gap:9px;padding:7px 11px;border:1px solid rgba(151,241,224,.22);border-radius:999px;background:rgba(141,240,223,.055);color:#b5f7ec;font-size:10px;font-weight:800;letter-spacing:.15em;text-transform:uppercase}
.to-live-dot{width:7px;height:7px;border-radius:50%;background:#8df0df;box-shadow:0 0 0 5px rgba(141,240,223,.09)}
.to-hero h1{max-width:720px;margin:24px 0 18px;font:500 clamp(45px,5.25vw,76px)/1.04 var(--display);letter-spacing:-.075em}
.to-hero h1 .to-line{display:block;white-space:nowrap;background:linear-gradient(105deg,#fff 8%,#e8e7f2 67%,#a5a2ba 100%);-webkit-background-clip:text;background-clip:text;color:transparent}
.to-hero h1 em{font-style:normal;color:var(--teal);background:linear-gradient(105deg,#9af4e8,#7b83ff);-webkit-background-clip:text;background-clip:text}
.to-hero-lede{max-width:550px;margin:0;color:#b7bbcb;font-size:clamp(14px,1.2vw,16px);line-height:1.85}
.to-search{display:flex;gap:8px;max-width:565px;margin-top:27px;padding:6px;border:1px solid rgba(255,255,255,.13);border-radius:17px;background:rgba(255,255,255,.055);box-shadow:inset 0 1px rgba(255,255,255,.05),0 20px 50px rgba(0,0,0,.18);backdrop-filter:blur(16px)}
.to-search input{width:100%;min-width:0;padding:10px 13px;border:0;outline:0;color:#fff;background:transparent;font-size:13px}
.to-search input::placeholder{color:#8f94a7}
.to-search button{flex:0 0 auto;border:0;border-radius:12px;padding:0 17px;background:#f6f5fc;color:#11121b;font-size:12px;font-weight:800;transition:background .2s}
.to-search button:hover{background:#bdf8ee}
.to-trust{display:flex;flex-wrap:wrap;gap:14px 20px;margin-top:17px;color:#9da3b7;font-size:11px}
.to-trust span:before{content:"✓";margin-inline-end:7px;color:var(--teal);font-weight:900}
.to-hero-stats{display:flex;align-items:center;gap:19px;margin-top:34px}
.to-stat{display:flex;align-items:baseline;gap:7px;white-space:nowrap}
.to-stat strong{font:500 25px/1 var(--display);letter-spacing:-.055em;color:#f6f5ff}
.to-stat span{font-size:10px;color:#a1a6b8}
.to-stat-sep{height:27px;width:1px;background:rgba(255,255,255,.13)}
.to-visual{position:relative;min-width:0;aspect-ratio:1/1;max-width:590px;margin-inline:auto;width:100%;display:grid;place-items:center;isolation:isolate}
.to-visual-glow{position:absolute;inset:6%;border-radius:50%;background:radial-gradient(circle,rgba(112,74,255,.23),rgba(48,177,173,.09) 36%,transparent 70%);filter:blur(15px);animation:toGlow 7s ease-in-out infinite alternate}
@keyframes toGlow{from{transform:scale(.94);opacity:.72}to{transform:scale(1.07);opacity:1}}
.to-orbit{position:absolute;inset:7%;border:1px solid rgba(255,255,255,.10);border-radius:50%;transform:rotate(-18deg) scaleY(.7);box-shadow:0 0 70px rgba(99,72,231,.08),inset 0 0 50px rgba(255,255,255,.015)}
.to-orbit:before,.to-orbit:after{content:"";position:absolute;width:7px;height:7px;border-radius:50%;background:var(--teal);box-shadow:0 0 18px rgba(141,240,223,.85)}
.to-orbit:before{left:18%;top:14%}.to-orbit:after{right:10%;bottom:17%;background:#a48cff;box-shadow:0 0 18px #a48cff}
.to-video-frame{position:absolute;inset:12%;overflow:hidden;border-radius:48% 48% 42% 42%;mask-image:radial-gradient(ellipse at center,black 36%,rgba(0,0,0,.85) 55%,transparent 75%);filter:saturate(.9) contrast(1.05);z-index:1}
.to-video-frame:after{content:"";position:absolute;inset:0;background:linear-gradient(135deg,rgba(8,9,15,.02),rgba(8,9,15,.22) 70%),radial-gradient(ellipse at 48% 48%,transparent 25%,rgba(8,9,15,.45) 80%);pointer-events:none}
.to-video{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:51% 8%;opacity:0;transition:opacity .9s linear}
.to-video.is-active{opacity:1}
.to-video-frame img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:51% 8%;opacity:.75}
.to-slab{position:absolute;z-index:2;width:62%;height:21%;left:18%;top:22%;border:1px solid rgba(255,255,255,.17);border-radius:17px;background:linear-gradient(115deg,rgba(255,255,255,.09),rgba(255,255,255,.025));box-shadow:0 18px 55px rgba(0,0,0,.2),inset 0 1px rgba(255,255,255,.15);backdrop-filter:blur(9px);transform:rotate(-12deg) skewX(-5deg);animation:toSlab 8s ease-in-out infinite}
.to-slab:nth-of-type(5){top:37%;left:22%;width:60%;animation-delay:-2.5s;background:linear-gradient(115deg,rgba(104,80,224,.17),rgba(255,255,255,.035))}
.to-slab:nth-of-type(6){top:52%;left:26%;width:57%;animation-delay:-5s;background:linear-gradient(115deg,rgba(44,174,166,.13),rgba(255,255,255,.025))}
@keyframes toSlab{0%,100%{transform:translateY(0) rotate(-12deg) skewX(-5deg)}50%{transform:translateY(-9px) rotate(-10deg) skewX(-5deg)}}
.to-slab-grid{position:absolute;inset:14px;border-radius:10px;opacity:.7;background-image:radial-gradient(circle,rgba(173,242,235,.85) 1px,transparent 1.5px);background-size:17px 17px;mask-image:linear-gradient(90deg,transparent,black 12%,black 80%,transparent)}
.to-slab-wave{position:absolute;left:5%;right:5%;top:50%;height:35%;border-top:1px solid rgba(155,240,231,.7);border-radius:50%;transform:rotate(-4deg);box-shadow:0 -5px 20px rgba(104,231,224,.13)}
.to-visual-label{position:absolute;right:1%;top:14%;z-index:4;padding:9px 12px;border:1px solid rgba(255,255,255,.15);border-radius:12px;background:rgba(13,14,23,.55);backdrop-filter:blur(14px);color:#c8f7ee;font-size:9px;font-weight:800;letter-spacing:.13em}
.to-glass-card{position:absolute;z-index:5;width:min(240px,48%);padding:15px 16px;border:1px solid rgba(255,255,255,.16);border-radius:16px;background:rgba(17,18,29,.68);box-shadow:0 18px 45px rgba(0,0,0,.22),inset 0 1px rgba(255,255,255,.08);backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px)}
.to-glass-card.top{left:0;top:19%}.to-glass-card.bottom{right:-1%;bottom:14%}
.to-glass-kicker{color:#aaf5e8;font-size:9px;font-weight:850;letter-spacing:.12em;text-transform:uppercase}
.to-glass-title{margin-top:6px;color:#f4f4fb;font:600 15px/1.3 var(--display);letter-spacing:-.035em}
.to-glass-meta{margin-top:5px;color:#a6adbf;font-size:10px}
.to-card-symbol{display:inline-grid;place-items:center;width:27px;height:27px;margin-bottom:8px;border-radius:9px;background:rgba(141,240,223,.1);color:var(--teal);font-size:14px}
.to-section{padding:72px 0}
.to-section-head{display:flex;justify-content:space-between;align-items:end;gap:22px;margin-bottom:25px}
.to-section-kicker{color:var(--teal);font-size:10px;font-weight:850;letter-spacing:.18em;text-transform:uppercase}
.to-section h2{margin:8px 0 5px;font:500 clamp(28px,3vw,42px)/1.15 var(--display);letter-spacing:-.06em}
.to-section-head p{margin:0;color:#9da4b8;font-size:13px}
.to-count{display:inline-flex;align-items:center;gap:8px;padding:8px 12px;border:1px solid var(--line);border-radius:999px;color:#c4c8d6;font-size:11px;white-space:nowrap}
.to-count strong{color:#fff}
.to-categories{display:flex;gap:8px;flex-wrap:wrap;margin:0 0 23px}
.ur-category{padding:9px 13px;border:1px solid rgba(255,255,255,.11);border-radius:999px;background:rgba(255,255,255,.025);color:#b8bdce;font-size:11px;font-weight:700;transition:background .2s,border-color .2s,color .2s}
.ur-category:hover,.ur-category.active{background:rgba(128,91,255,.15);border-color:rgba(155,130,255,.42);color:#e9e4ff}
.ur-tool-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:13px}
.ur-card{position:relative;display:flex;flex-direction:column;min-width:0;min-height:220px;padding:20px;border:1px solid rgba(255,255,255,.095);border-radius:19px;background:linear-gradient(145deg,rgba(255,255,255,.047),rgba(255,255,255,.018));box-shadow:inset 0 1px rgba(255,255,255,.035);transition:transform .28s cubic-bezier(.16,1,.3,1),border-color .25s,background .25s,box-shadow .25s;overflow:hidden}
.ur-card:before{content:"";position:absolute;left:0;right:0;top:0;height:1px;background:linear-gradient(90deg,transparent,rgba(141,240,223,.28),transparent);opacity:0;transition:opacity .25s}
.ur-card:hover{transform:translateY(-5px);border-color:rgba(141,240,223,.26);background:linear-gradient(145deg,rgba(141,240,223,.055),rgba(128,91,255,.04));box-shadow:0 22px 55px rgba(0,0,0,.2),inset 0 1px rgba(255,255,255,.07)}
.ur-card:hover:before{opacity:1}
.ur-card-top{display:flex;align-items:center;justify-content:space-between;gap:10px}
.ur-icon{display:grid;place-items:center;width:43px;height:43px;border:1px solid rgba(255,255,255,.1);border-radius:14px;background:linear-gradient(145deg,rgba(128,91,255,.18),rgba(141,240,223,.08));color:#c4b8ff;font:650 15px var(--display)}
.ur-tag{padding:5px 8px;border:1px solid rgba(255,255,255,.07);border-radius:999px;background:rgba(255,255,255,.035);color:#a7adbf;font-size:9px;font-weight:850;letter-spacing:.07em}
.ur-card h3{margin:16px 0 5px;color:#f0f1fa;font:600 17px/1.35 var(--display);letter-spacing:-.025em}
.ur-card p{margin:0;color:#9ea5b8;font-size:12px;line-height:1.75}
.ur-card-foot{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:auto;padding-top:19px;color:#c2b6ff;font-size:11px;font-weight:800}
.ur-card-foot small{color:#858da4;font-size:10px;font-weight:550}
.ur-card-foot span{transition:transform .2s}
.ur-card:hover .ur-card-foot span{transform:translateX(-2px)}
.ur-empty{grid-column:1/-1;padding:38px 20px;border:1px dashed rgba(255,255,255,.16);border-radius:18px;text-align:center;color:#a9afc0}
.to-ai-band{position:relative;overflow:hidden;display:grid;grid-template-columns:1.2fr .8fr;gap:30px;align-items:center;padding:clamp(24px,4vw,44px);border:1px solid rgba(141,240,223,.15);border-radius:26px;background:radial-gradient(ellipse at 80% 20%,rgba(128,91,255,.16),transparent 42%),linear-gradient(120deg,rgba(141,240,223,.055),rgba(255,255,255,.018))}
.to-ai-band h2{margin:8px 0 10px;font:500 clamp(25px,3vw,38px)/1.16 var(--display);letter-spacing:-.06em}
.to-ai-band p{max-width:620px;margin:0;color:#a8afc1;font-size:13px;line-height:1.8}
.to-ai-pills{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:8px}
.to-ai-pills span{padding:9px 11px;border:1px solid rgba(255,255,255,.11);border-radius:999px;background:rgba(255,255,255,.035);color:#cbd0de;font-size:10px}
.to-seo{max-width:880px;color:#9ca4b7;font-size:13px;line-height:1.9}
.to-seo h2{margin:28px 0 8px;color:#f1f2fa;font:500 24px/1.3 var(--display);letter-spacing:-.04em}
.to-faq{padding:15px 0;border-bottom:1px solid rgba(255,255,255,.09)}
.to-faq summary{cursor:pointer;color:#e8e9f4;font-size:13px;font-weight:700}
.to-faq p{margin:8px 0 0;color:#9ea5b8;font-size:12px}
.to-footer{border-top:1px solid rgba(255,255,255,.08);background:#07080d;padding:35px 0 22px;color:#b9bfce}
.to-footer-grid{display:flex;align-items:start;justify-content:space-between;gap:28px;flex-wrap:wrap}
.to-footer p{max-width:560px;margin:14px 0 0;color:#8e96aa;font-size:12px;line-height:1.8}
.to-footer-links{display:flex;gap:13px 18px;flex-wrap:wrap;font-size:11px;color:#aab0c0}
.to-footer-links a:hover{color:var(--teal)}
.to-copyright{margin-top:24px;padding-top:15px;border-top:1px solid rgba(255,255,255,.07);color:#71798d;font-size:10px}
.to-mobile-only{display:none}
.ur-tool{max-width:900px;margin:42px auto;padding:clamp(20px,4vw,38px);border:1px solid rgba(255,255,255,.1);border-radius:24px;background:linear-gradient(145deg,#141622,#0f1019);box-shadow:var(--shadow);color:#f3f4fc}
.ur-tool h2{font:600 clamp(26px,4vw,36px)/1.2 var(--display);letter-spacing:-.04em;margin:6px 0 12px}
.ur-tool p{color:#a8afc1}
.ur-eyebrow{font-size:10px!important;font-weight:850;letter-spacing:.15em;color:var(--teal)!important}
.ur-tool label{display:block;margin:14px 0 7px;color:#dfe2ee;font-size:12px;font-weight:750}
.ur-tool input:not([type=checkbox]),.ur-tool textarea,.ur-tool select{width:100%;min-width:0;padding:12px 13px;border:1px solid rgba(255,255,255,.15);border-radius:12px;background:#0b0d15;color:#f5f6fc}
.ur-tool textarea{resize:vertical;line-height:1.65}
.ur-tool input[type=checkbox]{margin-inline-end:7px}
.ur-actions{display:flex;align-items:center;flex-wrap:wrap;gap:10px;margin:14px 0}
.ur-actions label{display:flex;align-items:center;gap:4px;margin:0;font-weight:650}
.ur-actions button,.ur-tool button{border-radius:12px}
.ur-primary{border:0;background:linear-gradient(115deg,#6b46de,#8b65ff);color:#fff;padding:11px 16px;font-weight:800}
.ur-secondary{border:1px solid rgba(255,255,255,.14);border-radius:12px;padding:10px 14px;background:rgba(255,255,255,.045);color:#e8eaf4;font-weight:750}
.ur-form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
.ur-note{font-size:11px!important;background:rgba(141,240,223,.06);border:1px solid rgba(141,240,223,.12);border-radius:12px;padding:12px;color:#c5e8e4!important}
.ur-tool [role=status]{min-height:1.5em;font-size:12px}
.ur-coming{display:inline-block;margin-top:15px;color:#8f97aa;font-size:11px;font-weight:800}
.blog-posts{max-width:900px;margin:35px auto;padding:0 20px}
.post-outer,.post{border:1px solid rgba(255,255,255,.1);border-radius:22px;padding:clamp(20px,4vw,38px);margin-bottom:18px;background:linear-gradient(145deg,#141622,#0f1019);color:#f1f2fa}
.post-title{font:600 clamp(26px,4vw,38px)/1.2 var(--display);letter-spacing:-.04em}
.post-body{overflow-wrap:anywhere;color:#d3d6e2}.post-body img{max-width:100%;height:auto}.post-body iframe{max-width:100%}
.post-body a{color:#a8a0ff;text-decoration:underline;text-underline-offset:3px}
.ur-hidden,[hidden]{display:none!important}
html.motion-ready .to-reveal{opacity:0;transform:translateY(17px) scale(.99)}
html.motion-ready .to-reveal.is-visible{opacity:1;transform:none;transition:opacity .8s cubic-bezier(.16,1,.3,1),transform .8s cubic-bezier(.16,1,.3,1)}
html.motion-ready .to-hero-copy .to-reveal:nth-child(2){transition-delay:.08s}
html.motion-ready .to-hero-copy .to-reveal:nth-child(3){transition-delay:.15s}
html.motion-ready .to-hero-copy .to-reveal:nth-child(4){transition-delay:.22s}
html.motion-ready .to-hero-copy .to-reveal:nth-child(5){transition-delay:.3s}
html.motion-ready .to-hero-copy .to-reveal:nth-child(6){transition-delay:.36s}
html.motion-ready .ur-card{opacity:0;transform:translateY(15px) scale(.99)}
html.motion-ready .ur-card.is-visible{opacity:1;transform:none;transition:opacity .55s ease,transform .55s cubic-bezier(.16,1,.3,1),border-color .25s,background .25s,box-shadow .25s}
@media(max-width:1100px){.to-links{gap:13px}.to-links a{font-size:11px}.to-nav{gap:17px}.to-hero-grid{grid-template-columns:minmax(0,1fr) minmax(330px,.8fr);gap:28px}.to-hero h1{font-size:clamp(43px,5.4vw,65px)}.to-glass-card{padding:12px}.to-glass-title{font-size:13px}.ur-tool-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:820px){.to-wrap{width:min(100% - 34px,680px)}.to-links,.to-actions{display:none}.to-toolswitch{margin-inline-start:auto}.to-burger{display:grid;place-items:center;margin-inline-start:auto}.to-mobile-only{display:block}.to-hero{min-height:0;padding:56px 0 60px}.to-hero-grid{grid-template-columns:1fr;gap:24px}.to-hero-copy{max-width:690px}.to-hero h1{font-size:clamp(48px,9vw,76px)}.to-hero-lede{max-width:610px}.to-visual{width:min(100%,560px);margin-top:4px}.to-hero-stats{margin-top:26px}.to-section{padding:54px 0}.to-ai-band{grid-template-columns:1fr}.to-ai-pills{justify-content:flex-start}.to-section-head{align-items:start;flex-direction:column}.to-footer-grid{display:block}.to-footer-links{margin-top:20px}}
@media(max-width:560px){.to-wrap{width:calc(100% - 32px)}.to-topline .to-wrap{min-height:29px}.to-topline span:last-child{display:none}.to-nav{min-height:66px}.to-logo{font-size:21px}.to-mark{width:34px;height:34px}.to-hero{padding:45px 0 46px}.to-hero h1{font-size:clamp(39px,10.3vw,58px);letter-spacing:-.075em;margin-top:20px}.to-hero h1 .to-line{white-space:normal}.to-hero-lede{font-size:14px}.to-search{margin-top:21px}.to-search input{padding:10px 8px;font-size:12px}.to-search button{padding:0 12px;font-size:11px}.to-trust{gap:8px 12px;font-size:10px}.to-hero-stats{gap:11px;justify-content:space-between}.to-stat{gap:5px;display:flex;flex-direction:column;align-items:flex-start}.to-stat strong{font-size:23px}.to-stat span{font-size:9px}.to-stat-sep{height:32px}.to-visual{width:calc(100% + 10px);margin-inline:-5px}.to-glass-card{width:48%;padding:10px 11px;border-radius:13px}.to-glass-card.top{left:0;top:20%}.to-glass-card.bottom{right:0;bottom:12%}.to-glass-title{font-size:12px}.to-glass-meta{font-size:9px}.to-visual-label{font-size:8px;top:10%}.to-section{padding:42px 0}.to-section h2{font-size:30px}.ur-tool-grid{grid-template-columns:1fr;gap:10px}.ur-card{min-height:0;padding:17px}.ur-card h3{margin-top:12px}.to-count{font-size:10px}.to-ai-band{padding:22px}.to-ai-band h2{font-size:28px}.to-ai-pills span{font-size:9px}.ur-form-grid{grid-template-columns:1fr}.ur-tool{margin:20px 12px;padding:19px}.blog-posts{margin:22px auto;padding:0 12px}.to-footer{padding-top:29px}}
@media(max-width:350px){.to-hero-stats{gap:8px}.to-stat strong{font-size:21px}.to-stat span{font-size:8px}.to-search button{padding:0 9px}.to-glass-title{font-size:11px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*:before,*:after{animation:none!important;transition:none!important;scroll-behavior:auto!important}html.motion-ready .to-reveal,html.motion-ready .to-reveal.is-visible,html.motion-ready .ur-card,html.motion-ready .ur-card.is-visible{opacity:1;transform:none}}


html[data-theme=light]{color-scheme:light;--bg:#f4f5fb;--surface:#fff;--surface2:#f8f9ff;--ink:#141522;--muted:#626a80;--line:rgba(20,21,34,.12);--shadow:0 22px 65px rgba(28,29,56,.12)}
html[data-theme=light] body{background:#f4f5fb;color:#171824}
html[data-theme=light] .to-topline,html[data-theme=light] .to-footer{background:#11121b}
html[data-theme=light] .to-header{background:rgba(247,248,253,.88);border-color:rgba(20,21,34,.1)}
html[data-theme=light] .to-logo .to-word{color:#191a28}
html[data-theme=light] .to-links a{color:#4d5266}
