html[data-theme=light] .to-hero{background:radial-gradient(ellipse at 78% 40%,rgba(113,77,232,.14),transparent 42%),#f2f3fa;border-color:rgba(20,21,34,.08)}
html[data-theme=light] .to-hero:before{opacity:.28;background-image:linear-gradient(rgba(30,30,60,.08) 1px,transparent 1px),linear-gradient(90deg,rgba(30,30,60,.08) 1px,transparent 1px)}
html[data-theme=light] .to-hero h1 .to-line{background:linear-gradient(105deg,#161723 8%,#45465d 75%,#72748a 100%);-webkit-background-clip:text;background-clip:text;color:transparent}
html[data-theme=light] .to-hero h1 em{background:linear-gradient(105deg,#178c8c,#6750d7);-webkit-background-clip:text;background-clip:text}
html[data-theme=light] .to-hero-lede{color:#555c70}
html[data-theme=light] .to-search{background:rgba(255,255,255,.8);border-color:rgba(20,21,34,.12)}
html[data-theme=light] .to-search input{color:#151624}
html[data-theme=light] .to-search input::placeholder{color:#73798b}
html[data-theme=light] .to-trust,html[data-theme=light] .to-stat span{color:#646b7f}
html[data-theme=light] .to-stat strong{color:#202132}
html[data-theme=light] .to-stat-sep{background:rgba(20,21,34,.15)}
html[data-theme=light] .to-glass-card,html[data-theme=light] .to-visual-label{background:rgba(248,249,255,.78);border-color:rgba(20,21,34,.14)}
html[data-theme=light] .to-glass-title{color:#1d1e2e}
html[data-theme=light] .to-glass-meta{color:#62697e}
html[data-theme=light] .to-section h2,html[data-theme=light] .to-seo h2{color:#1b1c2b}
html[data-theme=light] .to-section-head p,html[data-theme=light] .to-seo,html[data-theme=light] .to-ai-band p{color:#5c6378}
html[data-theme=light] .ur-category{background:#fff;color:#51566b;border-color:rgba(20,21,34,.13)}
html[data-theme=light] .ur-category.active,html[data-theme=light] .ur-category:hover{background:#eeeaff;color:#5540c4}
html[data-theme=light] .ur-card{background:linear-gradient(145deg,#fff,#f9f9ff);border-color:rgba(20,21,34,.11)}
html[data-theme=light] .ur-card h3{color:#1e1f2e}
html[data-theme=light] .ur-card p,html[data-theme=light] .ur-card-foot small{color:#62697d}
html[data-theme=light] .ur-tag{background:#f1f1f9;color:#555b72;border-color:#e1e2ee}
html[data-theme=light] .to-ai-band{background:radial-gradient(ellipse at 80% 20%,rgba(128,91,255,.11),transparent 42%),linear-gradient(120deg,#eefaf7,#fff);border-color:rgba(20,21,34,.1)}
html[data-theme=light] .to-ai-band h2{color:#191a28}
html[data-theme=light] .to-ai-pills span{background:#fff;color:#464c62;border-color:rgba(20,21,34,.12)}
html[data-theme=light] .to-faq{border-color:rgba(20,21,34,.12)}
html[data-theme=light] .to-faq summary{color:#252637}
html[data-theme=light] .to-faq p{color:#5c6378}
html[data-theme=light] .ur-tool{background:#fff;color:#171824;border-color:rgba(20,21,34,.13)}
html[data-theme=light] .ur-tool label{color:#292a3b}
html[data-theme=light] .ur-tool input:not([type=checkbox]),html[data-theme=light] .ur-tool textarea,html[data-theme=light] .ur-tool select{background:#fafaff;color:#171824;border-color:#d7d9e6}
html[data-theme=light] .ur-secondary{background:#f5f5fb;color:#26283a;border-color:#d9dbe7}
html[data-theme=light] .post-outer,html[data-theme=light] .post{background:#fff;color:#191a28;border-color:#e0e2ee}
html[data-theme=light] .post-body{color:#454b60}


