  {"@context":"https://schema.org","@type":"WebSite","name":"Toolora","url":"https://utilityra.blogspot.com/","description":"Practical tools for study, office work, software development, files and image workflows.","potentialAction":{"@type":"SearchAction","target":"https://utilityra.blogspot.com/search?q={search_term_string}","query-input":"required name=search_term_string"}}

body.script:
(function(){
  'use strict';
  const root=document.documentElement;
  const reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const menu=document.getElementById('to-mobile-menu');
  const burger=document.getElementById('to-burger');
  function setMenu(open){if(!menu||!burger)return;menu.classList.toggle('open',open);burger.setAttribute('aria-expanded',String(open));burger.setAttribute('aria-label',open?'Close menu':'Open menu');burger.textContent=open?'×':'☰';}
  burger&&burger.addEventListener('click',function(e){e.stopPropagation();setMenu(!menu.classList.contains('open'));});
  menu&&menu.addEventListener('click',function(e){if(e.target.closest('a'))setMenu(false);});
  document.addEventListener('click',function(e){if(menu&&menu.classList.contains('open')&&!menu.contains(e.target)&&!burger.contains(e.target))setMenu(false);});
  document.addEventListener('keydown',function(e){if(e.key==='Escape'&&menu&&menu.classList.contains('open')){setMenu(false);burger.focus();}});
  const langButton=document.getElementById('ur-language')||document.getElementById('to-language');
  let language='ar';
  try{language=localStorage.getItem('toolora-language')||'ar';}catch(e){}
  function applyLanguage(lang){
    language=lang==='en'?'en':'ar';root.lang=language;root.dir=language==='ar'?'rtl':'ltr';
    document.querySelectorAll('[data-en],[data-ar]').forEach(function(el){const value=el.getAttribute('data-'+language);if(value!==null){if(el.hasAttribute('data-en-html')||el.hasAttribute('data-ar-html'))return;el.textContent=value;}});
    document.querySelectorAll('[data-en-html],[data-ar-html]').forEach(function(el){const value=el.getAttribute('data-'+language+'-html');if(value!==null)el.innerHTML=value;});
    const search=document.getElementById('to-search');if(search)search.placeholder=language==='ar'?'ابحث عن أداة: PDF، كلمات، درجات، JSON…':'Search tools: PDF, text, grades, JSON…';
    const lb=document.getElementById('ur-language');if(lb)lb.textContent=language==='ar'?'EN':'عربي';
    try{localStorage.setItem('toolora-language',language);}catch(e){}
    renderCategories(activeCategory);filterTools();
  }
  if(langButton)langButton.addEventListener('click',function(){applyLanguage(language==='ar'?'en':'ar');});
  const themeButton=document.getElementById('ur-theme');
  let theme='dark';try{theme=localStorage.getItem('toolora-theme')||'dark';}catch(e){}
  function applyTheme(value){theme=value==='light'?'light':'dark';root.dataset.theme=theme;if(themeButton){themeButton.textContent=theme==='dark'?'☼':'◐';themeButton.setAttribute('aria-label',theme==='dark'?'Switch to light mode':'Switch to dark mode');}try{localStorage.setItem('toolora-theme',theme);}catch(e){}}
  if(themeButton){themeButton.hidden=false;themeButton.addEventListener('click',function(){applyTheme(theme==='dark'?'light':'dark');});}
  applyTheme(theme);
  const grid=document.getElementById('ur-tool-grid');
  const cards=grid?Array.from(grid.querySelectorAll('.ur-card')):[];
  const categoriesEl=document.getElementById('to-categories');
  const search=document.getElementById('to-search');
  const form=document.getElementById('to-search-form');
  const empty=document.getElementById('to-empty');
  const count=document.getElementById('to-result-count');
  const live=document.getElementById('to-live-count');
  let activeCategory='All',query='';
  function labelForCategory(cat){if(cat==='All')return language==='ar'?'الكل':'All tools';const card=cards.find(c=>c.dataset.cat===cat);return card&&language==='ar'?(card.dataset.arCat||cat):cat;}
  function renderCategories(active){
    if(!categoriesEl)return;
    const names=['All'].concat(Array.from(new Set(cards.map(c=>c.dataset.cat).filter(Boolean))));
    categoriesEl.textContent='';
    names.forEach(function(cat){const b=document.createElement('button');b.type='button';b.className='ur-category'+(cat===active?' active':'');b.dataset.category=cat;b.textContent=labelForCategory(cat);b.setAttribute('aria-pressed',String(cat===active));b.addEventListener('click',function(){activeCategory=cat;renderCategories(cat);filterTools();});categoriesEl.appendChild(b);});
  }
  function normalize(value){return String(value||'').toLocaleLowerCase(language==='ar'?'ar':'en').normalize('NFKC');}
  function filterTools(){
    let visible=0;
    cards.forEach(function(card){
      const category=activeCategory==='All'||card.dataset.cat===activeCategory;
      const searchable=normalize((card.dataset.search||'')+' '+(card.textContent||'')+' '+(card.dataset.id||''));
      const matches=category&&(!query||searchable.includes(normalize(query)));
      card.hidden=!matches;if(matches)visible++;
    });
    if(empty)empty.hidden=visible>0;
    if(count)count.textContent=String(visible);
    if(live)live.textContent=language==='ar'?'عرض '+visible+' من '+cards.length+' أداة':'Showing '+visible+' of '+cards.length+' tools';
    if(grid)grid.setAttribute('aria-label',language==='ar'?'نتائج الأدوات':'Tool results');
  }
  if(search)search.addEventListener('input',function(){query=search.value.trim();filterTools();});
  if(form)form.addEventListener('submit',function(e){e.preventDefault();query=search?search.value.trim():'';filterTools();if(query.length>=2){const visible=cards.some(function(card){return !card.hidden;});track(visible?'search':'search_miss',{searchTerm:query});}document.getElementById('tools')?.scrollIntoView({behavior:reduce?'auto':'smooth',block:'start'});});
  if(grid)grid.addEventListener('click',function(e){const link=e.target.closest('.ur-card-foot');if(!link)return;const card=link.closest('.ur-card');if(card)track('tool_open',{toolKey:card.dataset.id||''});});
  if(grid){grid.setAttribute('aria-label','Tool catalog');cards.forEach(function(card){card.classList.add('to-reveal');});}
  if(!reduce){
    root.classList.add('motion-ready');
    const targets=Array.from(document.querySelectorAll('.to-reveal,.ur-card'));
    if('IntersectionObserver' in window){
      const observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target);}});},{threshold:.08,rootMargin:'0px 0px -24px 0px'});
      targets.forEach(function(el){observer.observe(el);});
    }else targets.forEach(function(el){el.classList.add('is-visible');});
  }else{
    document.querySelectorAll('.to-reveal,.ur-card').forEach(function(el){el.classList.add('is-visible');});
  }

  const params=new URLSearchParams(location.search);
  let ownerExcluded=false;
  try{ownerExcluded=localStorage.getItem('ur-owner-exclude')==='1';}catch(e){}
  const reviewMode=params.has('utilityra_review')||params.has('preview')||Boolean(navigator.webdriver)||/bot|crawler|spider|headless|playwright|puppeteer|lighthouse|google-inspectiontool|chatgpt|openai|anthropic|claude|perplexity|gemini|bingpreview/i.test(navigator.userAgent);
  const apiBase=String(window.UTILITYRA_API_BASE||'').replace(/\/+$/,'');
  let visitorKey='';
  try{visitorKey=sessionStorage.getItem('toolora-visitor')||'';if(!visitorKey){visitorKey=crypto.randomUUID?crypto.randomUUID():(String(Date.now())+'-'+Math.random().toString(36).slice(2));sessionStorage.setItem('toolora-visitor',visitorKey);}}catch(e){visitorKey='';}
  function track(eventType,extra){
    if(ownerExcluded||reviewMode||!apiBase||!visitorKey)return;
    const payload=Object.assign({visitorKey:visitorKey,eventType:eventType,path:location.pathname,referrer:document.referrer,reviewMode:reviewMode},extra||{});
    fetch(apiBase+'/api/analytics/event',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload),keepalive:true}).catch(function(){});
  }
  track('page_view');

  const year=document.getElementById('to-year');if(year)year.textContent=String(new Date().getFullYear());
  renderCategories(activeCategory);filterTools();applyLanguage(language);
  const a=document.getElementById('toVideoA'),b=document.getElementById('toVideoB');
  if(a&&b){
    if(reduce){a.removeAttribute('autoplay');[a,b].forEach(function(v){try{v.pause();v.currentTime=0;}catch(e){}});}
    else{
      let current=a,next=b,swapping=false;const fade=0.9;
      function play(v){const p=v.play();if(p&&typeof p.catch==='function')p.catch(function(){});}
      function tick(){if(swapping||!current.duration||!Number.isFinite(current.duration))return;if(current.duration-current.currentTime>fade)return;
        swapping=true;const outgoing=current,incoming=next;
        try{incoming.currentTime=0;}catch(e){}
        play(incoming);incoming.classList.add('is-active');outgoing.classList.remove('is-active');current=incoming;next=outgoing;
        window.setTimeout(function(){try{outgoing.pause();outgoing.currentTime=0;}catch(e){}swapping=false;},fade*1000+100);
      }
      play(a);a.addEventListener('timeupdate',tick);b.addEventListener('timeupdate',tick);
      document.addEventListener('visibilitychange',function(){if(document.hidden){a.pause();b.pause();}else if(!reduce)play(current);});
    }
  }
})();
